def verify(witness):
    # fail-closed; exact integer arithmetic only; deterministic; no I/O
    if not isinstance(witness, dict):
        return 'FAIL'
    if witness.get('N_max') != 8:
        return 'FAIL'
    if witness.get('r_min') != 3:
        return 'FAIL'
    if witness.get('domain') != list(range(1, 65)):
        return 'FAIL'

    def gcd(a, b):
        while b != 0:
            a, b = b, a % b
        return a

    checked = [0]

    def extend(chain):
        r_target = chain[0]  # unused placeholder

    def rec(chain, r):
        if len(chain) == r:
            checked[0] = checked[0] + 1
            x1 = chain[0]
            x2 = chain[1]
            xr = chain[r - 1]
            if gcd(x1, xr) != x1:
                return False
            if gcd(x2, xr) != x2:
                return False
            if x1 == x2:
                return False
            return True
        last = chain[-1]
        m = last
        while m <= 64:
            if m % last == 0:
                if not rec(chain + [m], r):
                    return False
            m = m + last
        return True

    for r in range(3, 9):
        for x1 in range(1, 65):
            if not rec([x1], r):
                return 'FAIL'
    if checked[0] == 0:
        return 'FAIL'
    return 'PASS'
